const inp = $input.first().json || {};
const inicio = String(inp.inicio_iso || '').trim();
const fin = String(inp.fin_iso || '').trim();
const contacto = String(inp.numero_contacto || '').replace(/\D/g, '');
const nombre = String(inp.nombre_contacto || 'Lead IA360').trim();
const wa = String(inp.wa_number || '').replace(/\D/g, '');
const sourceMsgId = String(inp.source_message_id || '').trim();
const titulo = String(inp.titulo || '').trim() || (`Reunión IA360 - ${nombre}`);
const dryRun = Boolean(inp.dry_run);

if (!inicio || !fin) {
  throw new Error('FALTAN_HORARIOS: inicio_iso y fin_iso son obligatorios en formato ISO 8601 UTC.');
}
if (!contacto) {
  throw new Error('FALTA_CONTACTO: numero_contacto es obligatorio para generar la propuesta.');
}

const startMs = Date.parse(inicio);
const endMs = Date.parse(fin);
if (Number.isNaN(startMs) || Number.isNaN(endMs)) {
  throw new Error('HORARIO_INVALIDO: inicio_iso y fin_iso deben ser fechas ISO 8601 validas.');
}
if (endMs <= startMs) {
  throw new Error('RANGO_INVALIDO: fin_iso debe ser posterior a inicio_iso.');
}

const tz = 'America/Mexico_City';
const dtf = new Intl.DateTimeFormat('en-CA', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  fractionalSecondDigits: 3,
  hour12: false
});

const getParts = (d) => {
  const formatted = dtf.formatToParts(d);
  const map = {};
  for (const p of formatted) map[p.type] = p.value;
  const hour = parseInt(map.hour, 10) % 24;
  const minute = parseInt(map.minute, 10);
  const second = parseInt(map.second, 10);
  const ms = parseInt(map.fractionalSecond || '0', 10);
  const dateStr = `${map.year}-${map.month}-${map.day}`;
  const totalDayMs = ((hour * 60 + minute) * 60 + second) * 1000 + ms;
  return { dateStr, hour, minute, second, ms, totalDayMs };
};

const startParts = getParts(new Date(startMs));
const endParts = getParts(new Date(endMs));

if (startParts.dateStr !== endParts.dateStr) {
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: el evento cruza de dia local (${startParts.dateStr} a ${endParts.dateStr} en ${tz}). Toda la reunion debe iniciar y terminar el mismo dia dentro de 08:00 a 20:00.`);
}
if (startParts.totalDayMs < 28800000) {
  const sStr = `${String(startParts.hour).padStart(2, '0')}:${String(startParts.minute).padStart(2, '0')}:${String(startParts.second).padStart(2, '0')}` + (startParts.ms > 0 ? `.${String(startParts.ms).padStart(3, '0')}` : '');
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: inicio local ${sStr} esta antes de las 08:00 (${tz}). Ventana permitida: 08:00 a 20:00.`);
}
if (endParts.totalDayMs > 72000000) {
  const eStr = `${String(endParts.hour).padStart(2, '0')}:${String(endParts.minute).padStart(2, '0')}:${String(endParts.second).padStart(2, '0')}` + (endParts.ms > 0 ? `.${String(endParts.ms).padStart(3, '0')}` : '');
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: fin local ${eStr} esta despues de las 20:00 (${tz}). Ventana permitida: 08:00 a 20:00.`);
}

let rawRes = inp.resources;
if (typeof rawRes === 'string') {
  try { rawRes = JSON.parse(rawRes); } catch (e) { rawRes = rawRes.split(',').map(s => s.trim()); }
}
if (!Array.isArray(rawRes) || rawRes.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources es obligatorio y debe ser un array no vacio de "calendar" y/o "zoom".');
}
const validSet = new Set(['calendar', 'zoom']);
for (const r of rawRes) {
  if (!validSet.has(r)) {
    throw new Error(`RECURSOS_INVALIDOS: recurso desconocido "${r}". Solo se permite "calendar" y/o "zoom".`);
  }
}
const unique = Array.from(new Set(rawRes));
const resources = ['calendar', 'zoom'].filter(r => unique.includes(r));
if (resources.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources no contiene recursos validos.');
}

const payload = {
  wa_number: wa || null,
  contact_number: contacto,
  source_message_id: sourceMsgId || null,
  kind: 'book',
  resources,
  start_utc: inicio,
  end_utc: fin,
  title: titulo,
  dry_run: dryRun
};

return [{ json: payload }];

const resp = $input.first().json || {};
const prep = $('Preparar Propuesta Reserva').first().json || {};
const ok = resp.ok === true;
const proposalId = resp.proposal_id || null;
const state = resp.state || (ok ? 'pending_owner_confirmation' : 'blocked');
const msg = resp.message || (ok
  ? `Propuesta de reunión generada (${prep.start_utc} a ${prep.end_utc}) y enviada a Alek para confirmación.`
  : `No se pudo generar la propuesta de reunión: ${resp.error || 'error desconocido'}`);

return [{
  json: {
    ok,
    estado: state === 'dry_run' ? 'dry_run' : (ok ? 'propuesta_creada' : 'error_propuesta'),
    state,
    proposal_id: proposalId,
    resources: prep.resources,
    start_utc: prep.start_utc,
    end_utc: prep.end_utc,
    titulo: prep.title,
    mensaje: msg,
    requires_owner_tap: ok && state === 'pending_owner_confirmation'
  }
}];

const raw = $input.first().json || {};
const headers = raw.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const expected = $env.N8N_CALENDAR_TOKEN;

if (!expected || auth !== `Bearer ${expected}`) {
  throw new Error('AUTH_FAILED: agenda local requiere bearer token valido de N8N_CALENDAR_TOKEN');
}

const inp = raw.body || raw;
const confirmado = String(inp.confirmado_por_owner || '').toLowerCase() === 'true';
if (!confirmado) {
  throw new Error('CONFIRMACION_REQUERIDA: agendar escribe en el calendario real de Alek. Requiere confirmacion del owner.');
}

const inicio = String(inp.inicio_iso || inp.start_utc || inp.start || '').trim();
const fin = String(inp.fin_iso || inp.end_utc || inp.end || '').trim();
if (!inicio || !fin) throw new Error('FALTAN_HORARIOS: inicio_iso y fin_iso son obligatorios en ISO 8601 UTC.');
const startMs = Date.parse(inicio);
const endMs = Date.parse(fin);
if (Number.isNaN(startMs) || Number.isNaN(endMs)) throw new Error('HORARIO_INVALIDO: usa ISO 8601.');
if (endMs <= startMs) throw new Error('RANGO_INVALIDO: el fin va despues del inicio.');

const tz = 'America/Mexico_City';
const dtf = new Intl.DateTimeFormat('en-CA', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  fractionalSecondDigits: 3,
  hour12: false
});

const getParts = (d) => {
  const formatted = dtf.formatToParts(d);
  const map = {};
  for (const p of formatted) map[p.type] = p.value;
  const hour = parseInt(map.hour, 10) % 24;
  const minute = parseInt(map.minute, 10);
  const second = parseInt(map.second, 10);
  const ms = parseInt(map.fractionalSecond || '0', 10);
  const dateStr = `${map.year}-${map.month}-${map.day}`;
  const totalDayMs = ((hour * 60 + minute) * 60 + second) * 1000 + ms;
  return { dateStr, hour, minute, second, ms, totalDayMs };
};

const startParts = getParts(new Date(startMs));
const endParts = getParts(new Date(endMs));

if (startParts.dateStr !== endParts.dateStr) {
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: el evento cruza de dia local (${startParts.dateStr} a ${endParts.dateStr} en ${tz}). Toda la reunion debe iniciar y terminar el mismo dia dentro de 08:00 a 20:00.`);
}
if (startParts.totalDayMs < 28800000) {
  const sStr = `${String(startParts.hour).padStart(2, '0')}:${String(startParts.minute).padStart(2, '0')}:${String(startParts.second).padStart(2, '0')}` + (startParts.ms > 0 ? `.${String(startParts.ms).padStart(3, '0')}` : '');
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: inicio local ${sStr} esta antes de las 08:00 (${tz}). Ventana permitida: 08:00 a 20:00.`);
}
if (endParts.totalDayMs > 72000000) {
  const eStr = `${String(endParts.hour).padStart(2, '0')}:${String(endParts.minute).padStart(2, '0')}:${String(endParts.second).padStart(2, '0')}` + (endParts.ms > 0 ? `.${String(endParts.ms).padStart(3, '0')}` : '');
  throw new Error(`AGENDA_OUTSIDE_BUSINESS_HOURS: fin local ${eStr} esta despues de las 20:00 (${tz}). Ventana permitida: 08:00 a 20:00.`);
}

let rawRes = inp.resources;
if (typeof rawRes === 'string') {
  try { rawRes = JSON.parse(rawRes); } catch (e) { rawRes = rawRes.split(',').map(s => s.trim()); }
}
if (!Array.isArray(rawRes) || rawRes.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources es obligatorio y debe ser un array no vacio de "calendar" y/o "zoom".');
}
const validSet = new Set(['calendar', 'zoom']);
for (const r of rawRes) {
  if (!validSet.has(r)) {
    throw new Error(`RECURSOS_INVALIDOS: recurso desconocido "${r}". Solo se permite "calendar" y/o "zoom".`);
  }
}
const unique = Array.from(new Set(rawRes));
const resources = ['calendar', 'zoom'].filter(r => unique.includes(r));
if (resources.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources no contiene recursos validos.');
}

const opId = String(inp.operation_id || inp.proposal_id || '').trim();
const alfabeto = 'abcdefghijkmnpqrstuvwxyz23456789';
let token = '';
for (let i = 0; i < 20; i += 1) token += alfabeto[Math.floor(Math.random() * alfabeto.length)];
const nombre = String(inp.nombre_contacto || inp.contact?.contactName || 'Lead IA360').trim();
const numero = String(inp.numero_contacto || inp.contact?.contactNumber || '').replace(/[^0-9]/g, '');
const titulo = String(inp.titulo || inp.summary || '').trim() || ('Reunión IA360 - ' + nombre);

return [{
  json: {
    token,
    resources,
    start: inicio,
    end: fin,
    summary: titulo,
    contact: { contactName: nombre, contactNumber: numero },
    operation_id: opId || null
  }
}];

const prep = $('Preparar Reserva').first().json;
const reserva = $('Reservar Calendar y Zoom').first().json || {};
const dbRow = $input.first() ? $input.first().json : null;

const resources = prep.resources || reserva.resources || [];
const components = reserva.components || {};
const persisted = Boolean(dbRow && dbRow.token);
const verified = Boolean(reserva.ok === true && reserva.verified === true && persisted);

const calComp = components.calendar;
const zoomComp = components.zoom;

const tz = 'America/Mexico_City';
const inicioFmt = new Intl.DateTimeFormat('es-MX', { timeZone: tz, dateStyle: 'full', timeStyle: 'short' }).format(new Date(prep.start));
const finFmt = new Intl.DateTimeFormat('es-MX', { timeZone: tz, timeStyle: 'short' }).format(new Date(prep.end));

return [{
  json: {
    ok: verified,
    verified,
    state: verified ? 'agendada' : (persisted ? 'parcial' : 'incierta'),
    estado: verified ? 'agendada' : (persisted ? 'parcial' : 'incierta'),
    resources,
    components,
    token: dbRow?.token || null,
    enlace_estable: dbRow?.token ? ('https://wa.geekstudio.dev/api/r/' + dbRow.token) : null,
    evento_id: calComp?.id || reserva.calendarEventId || null,
    calendar_event_id: calComp?.id || reserva.calendarEventId || null,
    zoom_meeting_id: zoomComp?.id || reserva.zoomMeetingId || null,
    zoom_join_url: zoomComp?.join_url || reserva.zoomJoinUrl || null,
    start_utc: prep.start,
    end_utc: prep.end,
    inicio_local: inicioFmt,
    fin_local: finFmt,
    titulo: prep.summary,
    resumen: dbRow?.token 
      ? `${prep.summary} agendada para el ${inicioFmt} a ${finFmt} (hora CDMX). Enlace: https://wa.geekstudio.dev/api/r/${dbRow.token}`
      : `${prep.summary} no pudo ser agendada completamente.`
  }
}];

const raw = $input.first() ? ($input.first().json || {}) : {};
const detalle = raw.error || raw.message || raw.motivo || JSON.stringify(raw).slice(0, 300);

return [{
  json: {
    ok: false,
    verified: false,
    state: 'no_agendada',
    estado: 'no_agendada',
    resources: $('Preparar Reserva').first()?.json?.resources || [],
    components: raw.components || {},
    error: detalle || 'El webhook de reserva no devolvió un recurso válido.',
    motivo: detalle || 'Falla en creación de cita con proveedor'
  }
}];
